<template><Teleport to="body"><div class="toast-stack" aria-live="polite"><TransitionGroup name="toast"><div v-for="toast in items" :key="toast.id" class="toast" :class="`is-${toast.tone||'neutral'}`" :role="toast.tone==='danger'?'alert':'status'" aria-atomic="true"><span class="toast__mark">{{mark(toast.tone)}}</span><span><b>{{toast.title}}</b><small v-if="toast.description">{{toast.description}}</small></span><button class="ln-focus-ring" type="button" :aria-label="`关闭提示：${toast.title}`" @click="$emit('dismiss',toast.id)">×</button></div></TransitionGroup></div></Teleport></template>
<script setup lang="ts">import type{LnToastItem}from'./types';defineProps<{items:readonly LnToastItem[]}>();defineEmits<{(e:'dismiss',id:string|number):void}>();function mark(tone?:string){return tone==='success'?'✓':tone==='warning'?'!':tone==='danger'?'×':'i'}</script>
<style scoped lang="scss">
.toast-stack{position:fixed;z-index:3200;right:18px;bottom:18px;width:min(360px,calc(100vw - 36px));display:grid;gap:8px}.toast{min-height:54px;padding:10px 10px 10px 12px;display:grid;grid-template-columns:22px 1fr 24px;align-items:center;gap:9px;border:1px solid var(--ln-border);border-radius:9px;background:var(--ln-surface-raised);box-shadow:var(--ln-shadow-popover);color:var(--ln-text);font-family:var(--ln-font);.toast__mark{width:20px;height:20px;display:grid;place-items:center;border-radius:50%;background:var(--ln-accent-soft);color:var(--ln-accent);font-size:11px;font-weight:700}.toast__mark+span{display:grid;gap:3px}b{font-size:12px;font-weight:570}small{color:var(--ln-text-secondary);font-size:11px}button{border:0;background:none;color:var(--ln-text-tertiary);font-size:16px;cursor:pointer}.is-success .toast__mark{background:color-mix(in srgb,var(--ln-success) 12%,transparent);color:var(--ln-success)}.is-warning .toast__mark{background:color-mix(in srgb,var(--ln-warning) 12%,transparent);color:var(--ln-warning)}.is-danger .toast__mark{background:color-mix(in srgb,var(--ln-danger) 12%,transparent);color:var(--ln-danger)}}.toast-enter-active,.toast-leave-active{transition:all var(--ln-normal)}.toast-enter-from,.toast-leave-to{opacity:0;transform:translateY(8px) scale(.98)}
</style>
